5. var builder = WebApplication.CreateBuilder(args);
6. 
7. // Train and save the model at startup
8. var modelPath = Path.Combine(AppContext.BaseDirectory, "churn-model.zip");
9. var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "customers.csv");
10. TrainModel(dataPath, modelPath);
11. 
12. // Register the pooled prediction engine (thread-safe for web apps)
13. builder.Services.AddPredictionEnginePool<CustomerInput, ChurnPrediction>()
14.     .FromFile(modelPath);
15. 
16. var app = builder.Build();
17. 
18. app.MapPost("/predict", (CustomerInput input, PredictionEnginePool<CustomerInput, ChurnPrediction> pool) =>
19. {
20.     var prediction = pool.Predict(input);
21.     return Results.Ok(new
22.     {
23.         WillChurn = prediction.PredictedLabel,
24.         Probability = prediction.Probability,
25.     });
26. });
27. 
28. app.Run();
