30. static void TrainModel(string dataPath, string modelPath)
31. {
32.     var mlContext = new MLContext(seed: 42);
33. 
34.     var data = mlContext.Data.LoadFromTextFile<CustomerInput>(
35.         dataPath, hasHeader: true, separatorChar: ',');
36. 
37.     var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.2);
38. 
39.     // Map "Yes"/"No" to boolean Label column
40.     var labelLookup = new Dictionary<string, bool> { ["Yes"] = true, ["No"] = false };
41.     var pipeline = mlContext.Transforms.Conversion.MapValue("Label", labelLookup, nameof(CustomerInput.Churned))
42.         .Append(mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerInput.Region)))
43.         .Append(mlContext.Transforms.Concatenate("Features",
44.             nameof(CustomerInput.Age),
45.             nameof(CustomerInput.Income),
46.             "RegionEncoded",
47.             nameof(CustomerInput.PurchaseHistory)))
48.         .Append(mlContext.Transforms.NormalizeMinMax("Features"))
49.         .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
50.             labelColumnName: "Label", featureColumnName: "Features"));
51. 
52.     var model = pipeline.Fit(split.TrainSet);
53. 
54.     // Evaluate on test set
55.     var predictions = model.Transform(split.TestSet);
56.     try
57.     {
58.         var metrics = mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: "Label");
59.         Console.WriteLine($"Model trained — AUC: {metrics.AreaUnderRocCurve:F4}, " +
60.                           $"Accuracy: {metrics.Accuracy:F4}, F1: {metrics.F1Score:F4}");
61.     }
62.     catch (ArgumentOutOfRangeException)
63.     {
64.         Console.WriteLine("Model trained — test set too small for full evaluation metrics. " +
65.                           "Add more data for reliable AUC/F1 scores.");
66.     }
67. 
68.     mlContext.Model.Save(model, data.Schema, modelPath);
69.     Console.WriteLine($"Model saved to {modelPath}");
70. }
